<!doctype html><html><head><meta charset="utf-8"><title>Sales Enquiries Report</title><style>body{font-family:Arial,sans-serif;font-size:11px;color:#222}h1{margin-bottom:2px}.meta{color:#666;margin-bottom:18px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #bbb;padding:6px;text-align:left}th{background:#eee}@media print{button{display:none}@page{size:landscape;margin:10mm}}</style></head><body><button onclick="window.print()">Print / Save as PDF</button><h1>Ageless One - Sales Enquiries</h1><div class="meta">Generated {{ now()->format('d M Y, h:i A') }}</div><table><thead><tr><th>Lead</th><th>Customer</th><th>Phone</th><th>Call</th><th>Source</th><th>Enquiry</th><th>Heat</th><th>Status</th><th>Follow-up</th><th>Proposal</th><th>Site Visit</th></tr></thead><tbody>@foreach($leads as $lead)<tr><td>{{ $lead->lead_code }}</td><td>{{ $lead->customer_name }}<br>{{ $lead->company_name }}</td><td>{{ $lead->phone }}</td><td>{{ ucfirst($lead->call_type) }}</td><td>{{ $lead->lead_source }}</td><td>{{ $lead->enquiry_for }}</td><td>{{ ucfirst($lead->temperature) }}</td><td>{{ ucwords(str_replace('_',' ',$lead->status)) }}</td><td>{{ optional($lead->next_follow_up_at)->format('d M Y') }}</td><td>{{ $lead->proposal_given?'Yes':'No' }}</td><td>{{ $lead->site_visit_done?'Yes':'No' }}</td></tr>@endforeach</tbody></table><script>window.onload=()=>window.print()</script></body></html>
